// Pages of their own website for Crawl4AI to read: the home page, contact and about.
const s = $json;
const site = /^https?:\/\//i.test(s.website) ? s.website.trim() : 'https://' + String(s.website).trim();
const root = (site.match(/^https?:\/\/[^\/?#]+/i) || [site])[0];
const urls = [site, root + '/contact', root + '/contact-us', root + '/about', root + '/about-us'];
return { json: { crawl_body: { urls: [...new Set(urls)].slice(0, s.crawl_max_pages),
  browser_config: { type: 'BrowserConfig', params: { headless: true } },
  crawler_config: { type: 'CrawlerRunConfig', params: { cache_mode: 'bypass', page_timeout: 30000 } } } } };

// What their website says: emails, phones, social profiles and photos (no AI), plus some text for Claude.
const s = $('Settings').first().json;
const r = $input.first().json;
const pages = (r.results || []).filter(p => p.success && (!p.status_code || p.status_code < 400));
const origin = u => (String(u).match(/^https?:\/\/[^\/?#]+/i) || [''])[0];
const abs = (src, base) => /^https?:/i.test(src) ? src : src.startsWith('//') ? 'https:' + src
  : src.startsWith('/') ? origin(base) + src : String(base).replace(/[^\/]*([?#].*)?$/, '') + src;
const links = pages.flatMap(p => [...(p.links?.external || []), ...(p.links?.internal || [])].map(l => l.href || ''));
const host = origin(pages[0]?.url || '').replace(/^https?:\/\/(www\.)?/i, '');
const badEmail = /\.(png|jpe?g|gif|webp|svg)$|example\.|sentry|wixpress|godaddy|domain\.com|yourname|@email\./i;
const emails = [...new Set(pages.map(p => p.html || '').join('\n').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])]
  .map(e => e.toLowerCase()).filter((e, i, a) => !badEmail.test(e) && a.indexOf(e) === i)
  .sort((a, b) => (host && b.endsWith(host)) - (host && a.endsWith(host)));
const pick = re => links.find(h => re.test(h) && !/sharer|share\.php|\/intent|\/plugins\/|\/dialog\//i.test(h)) || null;
const site = {
  pages_read: pages.length,
  emails: emails.slice(0, 3),
  phones: [...new Set(links.filter(h => h.startsWith('tel:')).map(h => decodeURIComponent(h.slice(4)).trim()))].slice(0, 2),
  instagram_url: pick(/instagram\.com\/[^/?#]+/i),
  facebook_url: pick(/facebook\.com\/[^?#]+/i),
  other_profiles: [/yelp\.com\/biz\//i, /linkedin\.com\/company\//i, /tiktok\.com\/@/i, /youtube\.com\/(c\/|channel\/|@)/i,
    /nextdoor\.com\/(pages|biz)\//i, /bbb\.org\//i, /angi\.com\//i, /houzz\.com\//i, /google\.com\/maps|g\.page\/|maps\.app\.goo\.gl/i]
    .map(pick).filter(Boolean),
  photo_urls: [...new Set(pages.flatMap(p => (p.media?.images || []).map(i => ({ ...i, src: abs(i.src, p.url) })))
    .filter(i => /^https?:/.test(i.src) && !/logo|icon|sprite|pixel|badge|\.svg/i.test(i.src))
    .sort((a, b) => (b.score || 0) - (a.score || 0)).map(i => i.src))].slice(0, 4),
};
if (r.error) site.error = String(r.error.message || r.error).slice(0, 200);
const site_text = pages.map(p => `## ${p.url}\n` + String(p.markdown?.raw_markdown ?? p.markdown ?? '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 3000)).join('\n\n').slice(0, s.site_text_max_chars);
return [{ json: { ...s, site, site_text } }];

// Builds the Claude request: website findings go in, so Claude only searches for what is missing.
const s = $json;
const business = JSON.stringify({ name: s.name, category: s.category, address: s.address,
  phone: s.phone, website: s.website || null, email: s.email || null }, null, 2);
const findings = s.site && s.site.pages_read
  ? JSON.stringify(s.site, null, 2) + (s.site_text ? `\n\nText from their website:\n${s.site_text}` : '')
  : 'Nothing - they have no website of their own, or it could not be read.';
const content = s.enrich_prompt.split('{business}').join(business).split('{sources}').join(s.enrichment_sources)
  .split('{website_findings}').join(findings);
return { json: { ...s, claude_body: {
  model: s.claude_model, max_tokens: 4000,
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: s.claude_max_searches },
          { type: 'web_fetch_20250910', name: 'web_fetch', max_uses: 2 }],
  messages: [{ role: 'user', content }] } } };

// Plug-in output: the lead exactly as it came in, plus `enrichment` (found data) or `error`.
// Facts from their own website win over web search; if Claude fails, the website facts are still kept.
const lead = $('Lead in').first().json;
const site = $('Build request').first().json.site || {};
const r = $input.first().json;
const uniq = a => [...new Set(a.filter(Boolean))];
const social = re => (re.test(lead.website || '') ? lead.website : null);
let d = {}, failed = '';
try {
  if (r.error) throw new Error(r.error.message || JSON.stringify(r.error));
  const text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  const m = [...text.matchAll(/<json>([\s\S]*?)<\/json>/g)].pop();
  d = JSON.parse(m ? m[1] : text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) { failed = `Claude: ${e.message}`; }
if (failed && !site.pages_read) return [{ json: { ...lead, error: failed } }];
const enrichment = { ...d,
  email: site.emails?.[0] || d.email || null,
  phone: d.phone || site.phones?.[0] || null,
  instagram_url: site.instagram_url || social(/instagram\.com/i) || d.instagram_url,
  facebook_url: site.facebook_url || social(/facebook\.com/i) || d.facebook_url,
  other_profiles: uniq([...(site.other_profiles || []), ...(d.other_profiles || [])]),
  photo_urls: uniq([...(site.photo_urls || []), ...(d.photo_urls || [])]).slice(0, 4),
  website_emails: site.emails || [],
  website_pages_read: site.pages_read || 0,
  ...(failed ? { notes: failed } : {}) };
return [{ json: { ...lead, enrichment } }];
